import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import './fichiersCSS/Etudiants.css';

const Etudiants = () => {
  const navigate = useNavigate();
  const [etudiants, setEtudiants] = useState([]);
  const [loading, setLoading] = useState(true);
  const [activeMenu, setActiveMenu] = useState("etudiants");
  const [searchTerm, setSearchTerm] = useState('');

  const menuItems = [
    { id: "dashboard", label: "Tableau de bord", icon: "📊" },
    { id: "cours", label: "Mes Cours", icon: "📚" },
    { id: "etudiants", label: "Étudiants", icon: "👨‍🎓" },
    { id: "notes", label: "Gérer les Notes", icon: "📝" },
    { id: "devoirs", label: "Devoirs", icon: "📋" },
    { id: "creer-cours", label: "Créer un Cours", icon: "➕" },
    { id: "creer-classe", label: "Créer une Classe", icon: "🏫" },
    { id: "profil", label: "Mon Profil", icon: "👤" }
  ];

  useEffect(() => {
    fetchEtudiants();
  }, []);

  const handleMenuClick = (menuId) => {
    setActiveMenu(menuId);
    switch(menuId) {
      case "dashboard": navigate("/dashboard-prof"); break;
      case "cours": navigate("/mes-cours"); break;
      case "etudiants": navigate("/etudiants"); break;
      case "notes": navigate("/notes"); break;
      case "devoirs": navigate("/mes-devoirs"); break;
      case "creer-cours": navigate("/creer-cours"); break;
      case "creer-classe": navigate("/creer-classe"); break;
      case "profil": navigate("/profil"); break;
      default: break;
    }
  };

  const fetchEtudiants = async () => {
    try {
      const token = localStorage.getItem('token');
      const response = await fetch('http://localhost:5000/api/etudiants', {
        headers: { 
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        }
      });

      if (response.ok) {
        const result = await response.json();
        setEtudiants(result.etudiants || []);
      }
    } catch (error) {
      console.error('Erreur chargement étudiants:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem("user");
    localStorage.removeItem("token");
    localStorage.removeItem("isAuthenticated");
    navigate("/login");
  };

  // Filtrer les étudiants selon la recherche
  const filteredEtudiants = etudiants.filter(etudiant =>
    etudiant.nom.toLowerCase().includes(searchTerm.toLowerCase()) ||
    etudiant.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
    (etudiant.class_name && etudiant.class_name.toLowerCase().includes(searchTerm.toLowerCase()))
  );

  const user = JSON.parse(localStorage.getItem('user'));

  if (loading) return (
    <div className="etudiants-container">
      {/* Sidebar */}
      <div className="etudiants-sidebar">
        {/* Sidebar content */}
      </div>
      <div className="etudiants-loading">
        <div>Chargement des étudiants...</div>
      </div>
    </div>
  );

  return (
    <div className="etudiants-container">
      
      {/* Sidebar */}
      <div className="etudiants-sidebar">
        <div className="etudiants-sidebar-header">
          <h2 className="etudiants-sidebar-title">Espace Professeur</h2>
          <p className="etudiants-sidebar-subtitle">Prof. {user?.nom}</p>
        </div>
        
        <nav className="etudiants-nav">
          {menuItems.map(item => (
            <div 
              key={item.id} 
              onClick={() => handleMenuClick(item.id)}
              className={`etudiants-menu-item ${activeMenu === item.id ? 'active' : ''}`}
            >
              <span>{item.icon}</span>
              <span>{item.label}</span>
            </div>
          ))}
        </nav>
        
        <div className="etudiants-logout-container">
          <button onClick={handleLogout} className="etudiants-logout-btn">
            🚪 Déconnexion
          </button>
        </div>
      </div>

      {/* Main Content */}
      <div className="etudiants-main">
        <header className="etudiants-header">
          <div className="etudiants-header-content">
            <div>
              <h1 className="etudiants-title">
                👨‍🎓 Mes Étudiants
              </h1>
              <p className="etudiants-subtitle">
                Gérer et consulter la liste de vos étudiants
              </p>
            </div>
            
            {/* Barre de recherche */}
            <div className="etudiants-search">
              <input
                type="text"
                placeholder="🔍 Rechercher un étudiant..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="etudiants-search-input"
              />
            </div>
          </div>
        </header><br></br><br></br><br></br>

        {filteredEtudiants.length === 0 ? (
          <div className="etudiants-empty">
            <div className="etudiants-empty-icon">👨‍🎓</div>
            <h3 className="etudiants-empty-title">
              {searchTerm ? 'Aucun étudiant trouvé' : 'Aucun étudiant inscrit'}
            </h3>
            <p className="etudiants-empty-text">
              {searchTerm 
                ? 'Aucun étudiant ne correspond à votre recherche' 
                : 'Les étudiants apparaîtront ici une fois inscrits dans vos classes'
              }
            </p>
            {searchTerm && (
              <button 
                onClick={() => setSearchTerm('')}
                className="etudiants-empty-btn"
              >
                Afficher tous les étudiants
              </button>
            )}
          </div>
        ) : (
          <div className="etudiants-list">
            {filteredEtudiants.map(etudiant => (
              <div key={etudiant.id} className="etudiants-item">
                <div className="etudiants-item-content">
                  <div className="etudiants-item-main">
                    <div className="etudiants-item-header">
                      <div className="etudiants-avatar">
                        {etudiant.nom.charAt(0).toUpperCase()}
                      </div>
                      <div>
                        <h3 className="etudiants-item-name">
                          {etudiant.nom}
                        </h3>
                        <p className="etudiants-item-email">
                          {etudiant.email}
                        </p>
                      </div>
                    </div>

                    <div className="etudiants-item-details">
                      <span className="etudiants-detail-item">
                        🆔 <strong>ID: {etudiant.id}</strong>
                      </span>
                      {etudiant.class_name && (
                        <span className="etudiants-detail-item">
                          🏫 <strong>Classe: {etudiant.class_name}</strong>
                        </span>
                      )}
                      <span className="etudiants-detail-item">
                        📅 <strong>Inscrit le: {new Date(etudiant.created_at).toLocaleDateString('fr-FR')}</strong>
                      </span>
                    </div>
                  </div>

                  <div className="etudiants-item-actions">
                    <button className="etudiants-action-btn profile">
                      👁️ Profil
                    </button>
                    <button className="etudiants-action-btn notes">
                      📝 Notes
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}

        {/* Statistiques */}
        {etudiants.length > 0 && (
          <div className="etudiants-stats">
            <h3 className="etudiants-stats-title">📊 Statistiques</h3>
            <div className="etudiants-stats-grid">
              <div className="etudiants-stat-card">
                <div className="etudiants-stat-value">{etudiants.length}</div>
                <div className="etudiants-stat-label">Total étudiants</div>
              </div>
              <div className="etudiants-stat-card">
                <div className="etudiants-stat-value classes">
                  {new Set(etudiants.map(e => e.class_id)).size}
                </div>
                <div className="etudiants-stat-label">Classes différentes</div>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default Etudiants;
